DO $design_catalog_migration$
DECLARE
  entries jsonb := $design_catalog_a9872f22d0903a6a$[{"manifest":{"slug":"nonstandard-image-size","name":"非标准图片尺寸","description":"仅在用户当前明确接受近似尺寸或接近比例时，使用原生图片的自定义 W:H 比例生成；不把近似授权带到新请求。","version":"1.0.0","category":"design","iconName":"aspect-ratio","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"image","intents":["nonstandard-image-size","approximate-image-size","custom-aspect-ratio"],"outputKinds":["raster-image"],"requiredTools":["generate_image"],"optionalTools":["edit_image","list_skills","use_skill"],"models":[{"role":"image","required":true,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；仅当前请求的明确近似授权或明确使用本技能可用，适配面板本身不构成授权，新请求不继承。","原生请求尺寸支持 1:3 至 3:1 的自定义 W:H 比例，并在可用原生尺寸中保持不超过 1% 的比例误差；服务商最终输出需按真实结果另行核对，它不承诺接近用户给出的像素宽高。","小目标会生成满足原生最小面积的较大图片；不能声称已缩放。超过 3:1 的比例必须由用户选择后续裁切或排版，当前无此工具时不能声称完成。","新图通过 generate_image.aspectRatio 传递尺寸，其余必填内容照常提供；编辑仅在用户要求改比例时传真实源图 UUID、aspectRatio 和 aspectRatioIntent=resize。不能虚构 width、height 参数或新工具。","显式 UI 比例优先；背景、GIF、压缩和原生画板写入不属于本流程。"],"examples":["做一张适配这个窄面板的图，尺寸差一点没关系，比例尽量接近 1400:500。"],"sources":[],"composition":{"role":"domain","stages":["design"]}}}},"content":"---\nname: nonstandard-image-size\ndescription: 仅在用户当前明确接受近似尺寸或接近比例时，使用原生图片的自定义 W:H 比例生成；不把近似授权带到新请求。\nmetadata:\n  author: loomic\n  version: \"1.0.0\"\n---\n\n# 非标准图片尺寸\n\n仅在用户当前请求明确接受“差不多尺寸”或“比例尽量靠近”等近似授权时使用本流程。用户明确要求使用本 Skill 也可触发；“适配面板”本身不等于允许近似，仍须有当前近似授权。只报目标像素、普通生图、讨论尺寸、否定生成或表示不要近似，都不是触发条件；此时不要加载本 Skill，也不要默认放宽尺寸要求。\n\n读取 [原生比例与交付边界](references/workflow.md) 后，先保留用户给出的宽高为比例 `W:H`。当前原生图片尺寸解析支持 `1:3` 到 `3:1` 内的自定义比例，并为请求选择比例误差不超过 1% 的原生尺寸。小目标也会按原生最小面积请求较大的像素尺寸；只能如实报告实际提交或结果记录中的原生尺寸，不能声称像素尺寸接近用户的小目标，不能声称已经缩放。服务商最终输出另行以真实结果核对比例误差，不能预先保证它仍在 1% 内。\n\n新图使用 `generate_image`，通过 `aspectRatio: \"W:H\"` 传递尺寸，其余必填内容照常提供；不能虚构 `width`、`height` 参数或新的尺寸工具。编辑已有图片时，只有用户明确要改变比例才使用 `edit_image`，并传真实源图 UUID 和 `aspectRatioIntent: \"resize\"`；否则保留源图比例。界面中明确选择的比例优先：若它与用户近似比例冲突，说明冲突并请用户选择，不覆盖界面选择。\n\n比例超过 `3:1` 或低于 `1:3` 时不默默钳制。说明当前原生生成无法接近该比例，并建议用户选择后续裁切或排版；当前没有对应工具时，不声称已经完成，也不创建、写入或修改原生画板。背景、GIF 和压缩是独立需求，不能因本流程自动加入或承诺。\n\n同一任务的微调可沿用已经明确的近似授权；新的生成请求不继承。用户对新尺寸提出精确要求时，精确要求优先，本流程不适用。所有图片结果只交付到无限画布，不创建、写入或修改原生画板。\n\n## Loomic 范围\n\n只讨论或说明限制时，不调用图片工具。加载 Skill 不等于生成授权、已提交或已完成；只依据实际任务回执与结果说明状态。不存在适用工具、已发布模型或真实源图 UUID 时如实说明，不能用提示词假装补齐能力。\n","files":[{"file_path":"references/workflow.md","content":"# 原生比例与交付边界\n\n## 触发与比例\n\n本流程只处理当前用户明确允许近似的生成请求，或当前明确要求使用本 Skill 的请求。单说“适配面板”仍不构成近似授权。将用户给出的宽高转换为 `W:H`，而非把它们当作工具参数。原生尺寸解析可接受 `1:3` 至 `3:1` 的正数比例；请求的原生宽高按 16 像素网格选择，比例误差不超过 1%，不会裁切或拉伸。\n\n不要预先承诺某一像素结果或最终比例误差。小于原生最小面积的目标仍会请求更大的原生图片；任务完成后只根据实际提交回执或结果记录报告原生宽高，并在有实际结果尺寸时再计算比例误差，明确它不是用户指定的小像素尺寸，也没有发生缩放。\n\n## 调用\n\n新图：通过 `generate_image.aspectRatio: \"W:H\"` 传递尺寸，其余必填内容照常提供。不要传不存在的 `width`、`height` 参数。\n\n编辑：只有用户明确要求把现有图改成新比例，才调用 `edit_image`，并传真实 `sourceAssetIds` UUID、`sourceUsage=edit`、`aspectRatio: \"W:H\"` 和 `aspectRatioIntent=resize`。没有改比例要求时保留来源画幅；没有真实 UUID 时不提交。\n\n界面已选比例覆盖助手推断。若其和用户允许的近似比例相冲突，先说明实际冲突，请用户选择使用界面比例还是修改界面选择。\n\n## 无法匹配的情况\n\n超过 `3:1` 或低于 `1:3` 的比例不能以相近原生比例代替。说明该限制，建议用户选择后续裁切或排版；没有可用裁切工具时只说明未完成，绝不创建、写入或修改原生画板。不要把背景、GIF、压缩、导出混入尺寸生成；这些必须有独立的当前请求和适用工具。\n","mime_type":"text/markdown"}]}]$design_catalog_a9872f22d0903a6a$::jsonb;
  entry jsonb;
  file_entry jsonb;
  target_id uuid;
BEGIN
  -- Lock existing rows before ownership checks. A competing slug INSERT is
  -- checked again by the guarded UPSERT below, so it cannot grant ownership.
  PERFORM 1 FROM public.skills AS s
    WHERE s.slug IN (SELECT item->'manifest'->>'slug' FROM jsonb_array_elements(entries) AS item)
    ORDER BY s.slug FOR UPDATE;
  IF EXISTS (
    SELECT 1 FROM public.skills AS s
    WHERE s.slug IN (SELECT item->'manifest'->>'slug' FROM jsonb_array_elements(entries) AS item)
      AND (s.source IS DISTINCT FROM 'system' OR s.created_by IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'Design skill catalog conflicts with a non-owned skill; nothing was changed';
  END IF;

  FOR entry IN SELECT value FROM jsonb_array_elements(entries) LOOP
    target_id := NULL;
    INSERT INTO public.skills AS owned (slug, name, description, author, version, license, category, icon_name, source, skill_content, metadata, is_featured)
    VALUES (entry->'manifest'->>'slug', entry->'manifest'->>'name', entry->'manifest'->>'description', 'Loomic',
      entry->'manifest'->>'version', entry->'manifest'->>'license', entry->'manifest'->>'category',
      entry->'manifest'->>'iconName', 'system', entry->>'content', entry->'manifest'->'metadata', true)
    ON CONFLICT (slug) DO UPDATE SET
      name = EXCLUDED.name, description = EXCLUDED.description, author = EXCLUDED.author,
      version = EXCLUDED.version, license = EXCLUDED.license, category = EXCLUDED.category,
      icon_name = EXCLUDED.icon_name, skill_content = EXCLUDED.skill_content,
      metadata = COALESCE(owned.metadata, '{}'::jsonb) || EXCLUDED.metadata, updated_at = now()
    WHERE owned.source = 'system' AND owned.created_by IS NULL
    RETURNING id INTO target_id;
    IF target_id IS NULL THEN
      RAISE EXCEPTION 'Design skill ownership changed concurrently; nothing was changed';
    END IF;
    FOR file_entry IN SELECT value FROM jsonb_array_elements(entry->'files') LOOP
      INSERT INTO public.skill_files (skill_id, file_path, content, mime_type)
      VALUES (target_id, file_entry->>'file_path', file_entry->>'content', file_entry->>'mime_type')
      ON CONFLICT (skill_id, file_path) DO UPDATE SET
        content = EXCLUDED.content, mime_type = EXCLUDED.mime_type, updated_at = now();
    END LOOP;
  END LOOP;
END;
$design_catalog_migration$;
